     * @dev returns latest published roots tree root
     * @return rootsRoot
     */
    function getLatestPublishedRootsRoot() public view returns (uint256) {
        return _getIdentityBaseStorage().identity.latestPublishedTreeRoots.rootsRoot;
    }

